describe('Empty State Illustration in Table', () => {
  beforeEach(() => {
    cy.visit('/table-list');
  });

  it('should display empty state illustration when table has no data', () => {
    // Verify empty state message is visible
    cy.get('[data-testid="empty-state-message"]').should('be.visible');
    cy.get('[data-testid="empty-state-message"]').should('contain', 'No data found');

    // Verify empty state icon is displayed
    cy.get('[data-testid="empty-state-icon"]').should('be.visible');
    cy.get('[data-testid="empty-state-icon"]').should('have.class', 'empty-state-icon');

    // Verify table header is still visible
    cy.get('[data-testid="table-header"]').should('be.visible');
    cy.get('[data-testid="table-header"]').should('contain', 'No data');

    // Verify no rows are displayed
    cy.get('[data-testid="table-row"]').should('not.exist');

    // Verify empty state styling is applied
    cy.get('[data-testid="empty-state-container"]').should('have.class', 'empty-state');
  });

  it('should handle empty state when data is loaded and then cleared', () => {
    // Load data into table
    cy.intercept('GET', '/api/table-data').as('loadData');
    cy.wait('@loadData');

    // Verify data is displayed
    cy.get('[data-testid="table-row"]').should('have.length.greaterThan', 0);

    // Clear data
    cy.get('[data-testid="clear-data-button"]').click();

    // Verify empty state is displayed after clearing
    cy.get('[data-testid="empty-state-message"]').should('be.visible');
    cy.get('[data-testid="empty-state-message"]').should('contain', 'No data found');

    // Verify empty state icon is still visible
    cy.get('[data-testid="empty-state-icon"]').should('be.visible');

    // Verify table header still shows empty state message
    cy.get('[data-testid="table-header"]').should('contain', 'No data');

    // Verify no rows are displayed
    cy.get('[data-testid="table-row"]').should('not.exist');
  });
});
